<script lang="ts">
	import { Constants, Mutex } from "$lib";
	import * as Dialog from "$lib/components/ui/dialog";
	import * as Empty from "$lib/components/ui/empty";
	import * as InputGroup from "$lib/components/ui/input-group";
	import { SearchIcon, X } from "@lucide/svelte";
	import type { Snippet } from "svelte";
	import { toast } from "svelte-sonner";
	import { createLatestSearch } from "$platform/latest-search";
	import Button from "./ui/button/button.svelte";
	import ScrollArea from "./ui/scroll-area/scroll-area.svelte";
	import Spinner from "./ui/spinner/spinner.svelte";

	const {
		onSearch,
		children
	}: {
		onSearch: (query: string, signal?: AbortSignal) => Promise<FeedResponse<any>>;
		children: Snippet<[{ data: any }]>;
	} = $props();
  const mutex = new Mutex();
  let feed = $state<FeedResponse<any>>();
  let query = $state<string>("");
  const latest = createLatestSearch(busy => busy ? mutex.lock() : mutex.unlock());
  const search = (delay: number) => {
    const text = query, callback = onSearch; feed = undefined;
    if (!text.length) { latest.invalidate(); return; }
    latest.schedule(delay, signal => callback(text, signal), result => { if (query === text && callback === onSearch) feed = result; }, error => {
      if (error instanceof Constants.Error.Error) toast.error(error.title, { description: error.body });
      else toast.error("Search failed", { description: error instanceof Error ? error.message : "Try the current query again." });
    });
  };
  $effect.pre(() => { onSearch; latest.invalidate(); feed = undefined; });
  const onInput = () => search(500);
  const onSubmit = (event?: SubmitEvent) => { event?.preventDefault(); search(0); };
</script>

<div class="flex shrink-0 items-center gap-1">
	<InputGroup.Root class="!border-border rounded-none !border-x-0 !border-t-0 py-5 !ring-0 !ring-transparent">
		<InputGroup.Input
			class="w-0 flex-auto truncate"
			bind:value={query}
			placeholder="Search..."
			autocomplete="off"
			oninput={onInput}
			onsubmit={onSubmit}
		/>
		<InputGroup.Addon>
			{#if $mutex}
				<Spinner />
			{:else}
				<SearchIcon />
			{/if}
		</InputGroup.Addon>
		<InputGroup.Addon align="inline-end">
			<Dialog.Close>
				{#snippet child({ props })}
					<Button class="-mr-0.75" type="button" variant="ghost" size="icon" {...props}>
						<X class="size-5" />
					</Button>
				{/snippet}
			</Dialog.Close>
		</InputGroup.Addon>
	</InputGroup.Root>
</div>
<div class="flex h-full flex-auto overflow-hidden p-2">
	<ScrollArea class="w-full flex-auto" scrollbarYClasses="hidden">
		{#if $mutex}
			<Empty.Root>
				<Empty.Header>
					<Empty.Description>Searching...</Empty.Description>
				</Empty.Header>
			</Empty.Root>
		{:else if feed}
			{#if feed?.total}
				{@render children({ data: feed.data })}
			{:else}
				<Empty.Root>
					<Empty.Header>
						<Empty.Description>No results found</Empty.Description>
					</Empty.Header>
				</Empty.Root>
			{/if}
		{:else}
			<Empty.Root>
				<Empty.Header>
					<Empty.Description>Type to search…</Empty.Description>
				</Empty.Header>
			</Empty.Root>
		{/if}
	</ScrollArea>
</div>
